		&XMLWhenFilterLoading;
		&XMLWhenFilterClosing;





select @ngay_tu as ngay_tu, @ngay_den as ngay_den
-- HoangTNB sửa ngày từ/ngày đến
exec zrpt_bctc @ngay_tu, @ngay_den, @form, @ma_dvcs, @@language, @@userID, @@admin, '@@sysDatabaseName'







			&OutlineEntry;
			&JavascriptReportFilter; 

function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	changeLookupReadonly(f, 'ma_dvcs');
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid, x = f.getItem('form').value; 
			g._hiddenFields = [
				{Fields: 'tknh, ton_quy, so_bi_pt, so_kha_dung', Value: (x == '20' || x == '30' || x == '40')}
				, {Fields: 'nh_vv1, ten_nh, ten_loai_sp, so_ct, ngay_ct, s2, doi_tuong, tk, tk_du', Value: (x == '10')}
				, {Fields: 'ten_tc, noi_dung_thu, so_tien_thu ', Value: (x == '10' || x == '40')}
				, {Fields: 'noi_dung_chi, so_tien_chi, tien_goc, tien_lai, ten_loai', Value: (x == '10' || x == '20' || x == '30')}
			];
			g._alterTitle = [null, [['%s1', f.getItem('ngay_tu').value, true], ['%s2', f.getItem('ngay_den').value, true]]];
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}




